command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: GEISTERSCHRECKEN (Die robusten Wurzeln)
// ==========================================

(async () => {
    if (!globalThis.DSK) {
        const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
        if (fwMacro) await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150)); 
    }
    if (!globalThis.DSK) return ui.notifications.error("Das DSK-Framework fehlt!");
    const DSK_FW = globalThis.DSK; 

    let casterToken = canvas.tokens.controlled[0];
    const casterActor = casterToken?.actor || game.user.character;
    if (!casterActor) return ui.notifications.warn("Bitte wähle zuerst deinen Token aus!");

    if (!casterToken) casterToken = canvas.tokens.placeables.find(t => t.actor?.id === casterActor.id);
    let qsWert = casterActor.getFlag("world", "letzteGabenQS") || 1;
    if (casterActor.getFlag("world", "letzteGabenQS")) await casterActor.unsetFlag("world", "letzteGabenQS"); 
    if (typeof testData !== "undefined" && testData) qsWert = Number(testData?.result?.QL || testData?.qualityStep || qsWert);

    const gabenName = "Geisterschrecken"; const ahne = "Zerzal"; const finalEffektName = `${gabenName} (${ahne})`;
    const casterName = DSK_FW.ResolveTokenName(casterActor); const debuffName = `Geisterschreck - Furcht - von ${casterName}`; 
    const dauerMinuten = qsWert * 3; const reichweite = 16; const iconBild = DSK_FW.Symbol(ahne); 

    const descCaster = `Du strahlst eine Aura aus. Jeder Geist im Umkreis von ${reichweite} Schritt erhält ${qsWert} Stufe(n) Furcht.`;
    for (let ef of casterActor.effects) { if ((ef.name || ef.label) === finalEffektName) await ef.delete(); }

    await DSK_FW.Effekt.Anwenden({
        name: finalEffektName, ahne: ahne, beschreibung: descCaster, gabeZiel: "erwachte", qs: qsWert, ziel: casterActor,
        flags: { dsk: { qs: qsWert, isGeisterschreckenAura: true, debuffName: debuffName } } 
    });

    if (DSK_FW.EffektEnde) DSK_FW.EffektEnde.Register("geisterschrecken", finalEffektName, "Die furchteinflößende Aura verblasst. Die Geister in der Umgebung erholen sich.");

    await ChatMessage.create({ speaker: { alias: "System" }, content: `<div style="font-family: 'Signika', sans-serif;">${DSK_FW.UI.Header(finalEffektName, iconBild)}<div class="dskbox2" style="margin-top:10px; text-align:center;"><p style="margin-bottom: 8px;"><b>${casterName}</b> entfesselt eine erschreckende Aura!</p><hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;"><p style="margin-bottom: 8px;">Jeder Geist im Umkreis von <b>${reichweite} Schritt</b> erhält automatisch <b>${qsWert} Stufe(n) Status Furcht</b>.<br><br><span style="color:#555; font-size:0.85em;"><i>(Dies gilt sofort für bereits platzierte Geister und für alle, die sich später in den Umkreis bewegen!)</i></span></p><hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;"><p style="margin-bottom: 8px; font-weight:bold;">Wirkungsdauer:<br>${dauerMinuten} Minuten (QS ${qsWert})</p></div></div>` });

    globalThis.geisterschreckenHooks = globalThis.geisterschreckenHooks || {};
    if (globalThis.geisterschreckenHooks[casterActor.id]) { Hooks.off("updateToken", globalThis.geisterschreckenHooks[casterActor.id].hookId); clearTimeout(globalThis.geisterschreckenHooks[casterActor.id].timer); }

    const checkGeisterAura = async () => {
        const activeGM = game.users.find(u => u.isGM && u.active);
        if (activeGM && game.user.id !== activeGM.id) return;

        const liveCasterToken = canvas.tokens.placeables.find(t => t.actor?.id === casterActor.id);
        if (!liveCasterToken) return;

        for (let t of canvas.tokens.placeables) {
            let tActor = t.actor;
            if (!tActor || tActor.id === casterActor.id || !DSK_FW.Effekt.CheckTarget(tActor, "geist")) continue;

            const inRange = DSK_FW.Distanz(liveCasterToken, t) <= reichweite;
            const existingDebuff = tActor.effects.find(e => (e.name || e.label) === debuffName);

            if (inRange && !existingDebuff) {
                await tActor.createEmbeddedDocuments("ActiveEffect", [{
                    name: debuffName, type: "base", img: iconBild, description: `Erschreckende Aura von ${casterName}. (QS: ${qsWert})`,
                    changes: [{ key: "system.status.feared", mode: 2, value: String(qsWert), priority: 20 }],
                    statuses: ["feared"],
                    flags: { dsk: { sourceAura: casterActor.id, qs: qsWert } }
                }]);
            } else if (!inRange && existingDebuff) { await existingDebuff.delete(); }
        }
    };

    globalThis.geisterschreckenHooks[casterActor.id] = { hookId: Hooks.on("updateToken", (doc, change) => { if (change.x !== undefined || change.y !== undefined) { clearTimeout(globalThis.geisterschreckenHooks[casterActor.id].timer); globalThis.geisterschreckenHooks[casterActor.id].timer = setTimeout(checkGeisterAura, 500); } }) };
    if (!globalThis.LunasAuraCleanup) {
        globalThis.LunasAuraCleanup = true;
        Hooks.on("deleteActiveEffect", async (effect) => {
            if (!game.user.isGM) return;
            if (effect.getFlag("dsk", "isGeisterschreckenAura")) {
                const dName = effect.getFlag("dsk", "debuffName");
                const casterId = effect.parent?.id;
                if (globalThis.geisterschreckenHooks && globalThis.geisterschreckenHooks[casterId]) { Hooks.off("updateToken", globalThis.geisterschreckenHooks[casterId].hookId); delete globalThis.geisterschreckenHooks[casterId]; }
                if (dName) { for (let t of canvas.tokens.placeables) { if (t.actor) { let debuff = t.actor.effects.find(e => (e.name || e.label) === dName); if (debuff) await debuff.delete(); } } }
            }
        });
    }
    checkGeisterAura(); 
})();
